using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class BFFSurvey {
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||!s.path.EndsWith("Level_B4_Circular.unity"))throw new Exception("B4 edit required");string repo=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));string backup=repo+"/SourceAssets/B4_FullFloor/B4_before.unity.backup";if(!File.Exists(backup)){string temp=Path.Combine(Path.GetTempPath(),"B4_FullFloor_Backup_"+DateTime.Now.ToString("yyyyMMdd_HHmmss")+".unity");if(!EditorSceneManager.SaveScene(s,temp,true))throw new Exception("Backup failed");File.Copy(temp,backup);}
  if(s.isDirty)EditorSceneManager.SaveScene(s);
  var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B4_")).transform;var old=root.GetComponentsInChildren<Transform>(true).Select(t=>new{id=GlobalObjectId.GetGlobalObjectIdSlow(t).ToString(),name=t.name,pos=new[]{t.position.x,t.position.y,t.position.z},rot=new[]{t.rotation.x,t.rotation.y,t.rotation.z,t.rotation.w},scale=new[]{t.localScale.x,t.localScale.y,t.localScale.z},active=t.gameObject.activeSelf}).ToArray();File.WriteAllText(repo+"/SourceAssets/B4_FullFloor/scene_before.json",JsonConvert.SerializeObject(old,Formatting.Indented));
  string A="Assets/Afrer_Seconds/05.Model/";string[] paths=Directory.GetFiles(Path.Combine(Application.dataPath,"Afrer_Seconds/05.Model/Props/B5"),"SF_*.fbx").Select(f=>A+"Props/B5/"+Path.GetFileName(f)).Concat(Directory.GetFiles(Path.Combine(Application.dataPath,"Afrer_Seconds/05.Model/Props/B4"),"BO_*.fbx").Select(f=>A+"Props/B4/"+Path.GetFileName(f))).ToArray();var assets=paths.Select(p=>{var g=AssetDatabase.LoadAssetAtPath<GameObject>(p);var rs=g.GetComponentsInChildren<Renderer>();var b=rs[0].bounds;foreach(var r in rs.Skip(1))b.Encapsulate(r.bounds);return new{asset=p,name=Path.GetFileNameWithoutExtension(p),size=new[]{b.size.x,b.size.y,b.size.z},center=new[]{b.center.x,b.center.y,b.center.z},materials=rs.SelectMany(r=>r.sharedMaterials).Select(m=>m.name).Distinct().ToArray()};}).ToArray();File.WriteAllText(repo+"/SourceAssets/B4_FullFloor/asset_catalog.json",JsonConvert.SerializeObject(assets,Formatting.Indented));return new{backup,existing=old.Length,assets=assets.Length};}
}
